// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount > 0);
        vm.assume(data.length <= 64);
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        c.sendMoney(address(rec), amount, data);
        uint256 recorded = rec.totalValue();
        assertTrue(recorded == amount, "sendMoney must forward value to target");
    }
}

contract Recorder {
    uint256 public totalValue;

    fallback() external payable {
        totalValue += msg.value;
    }

    receive() external payable {
        totalValue += msg.value;
    }
}
